#!/usr/bin/env python3
import os, sys, re

ROOT = "/mnt/e/个人知识/OneNote/java"

# Recursive search
results = []
for dirpath, dirs, files in os.walk(ROOT):
    for name in files:
        if not name.endswith(".md"):
            continue
        path = os.path.join(dirpath, name)
        rel = os.path.relpath(path, ROOT)
        with open(path, encoding="utf-8") as fh:
            content = fh.read()
        lines = content.split("\n")
        # Find fenced regions
        pending_start = None
        pending_open = None
        issues = []
        for i, line in enumerate(lines, 1):
            s = line.strip()
            m = re.match(r"^(`{3,})(.*)$", s)
            if m:
                fence = m.group(1)
                rest = m.group(2).strip()
                if pending_start is None:
                    pending_start = i
                    pending_open = rest
                else:
                    # closing fence
                    if i - pending_start <= 1:
                        issues.append(f"L{pending_start}: {pending_open!r} -> L{i} (empty body)")
                    elif not pending_open and not rest:
                        # both fences empty - empty code block
                        pass
                    pending_start = None
                    pending_open = None
        if pending_start is not None:
            issues.append(f"L{pending_start}: unclosed fence {pending_open!r}")
        # Find unfenced (no language) opens
        for i, line in enumerate(lines, 1):
            s = line.strip()
            if s.startswith("```") and len(s) > 3 and not s[3:].strip():
                # no language tag (closing fence is OK to be empty)
                pass
        if issues:
            results.append((rel, issues))

for rel, issues in results:
    print(f"=== {rel} ===")
    for x in issues:
        print(" ", x)
print(f"\nTotal files with fence issues: {len(results)}")

