#!/usr/bin/env python3
import os, sys, re

ROOT = "E:/个人知识/OneNote/java"

results = []
for dirpath, dirs, files in os.walk(ROOT):
    for name in files:
        if not name.endswith(".md"):
            continue
        path = os.path.join(dirpath, name)
        rel = os.path.relpath(path, ROOT)
        with open(path, encoding="utf-8") as fh:
            content = fh.read()
        lines = content.split("\n")
        pending_start = None
        pending_open = None
        empty_open = []
        issues = []
        unclosed = False
        for i, line in enumerate(lines, 1):
            s = line.strip()
            m = re.match(r"^(`{3,})(.*)$", s)
            if m:
                fence = m.group(1)
                rest = m.group(2).strip()
                if pending_start is None:
                    pending_start = i
                    pending_open = rest
                    # check if open fence has no language tag
                    if not rest:
                        empty_open.append(i)
                else:
                    if i - pending_start <= 1:
                        issues.append(f"L{pending_start}-{i}: empty body")
                    pending_start = None
                    pending_open = None
        if pending_start is not None:
            unclosed = True
            issues.append(f"L{pending_start}: unclosed fence")
        if empty_open or issues or unclosed:
            results.append((rel, empty_open, issues, unclosed))

for rel, empty_open, issues, unclosed in results:
    print(f"=== {rel} ===")
    if empty_open:
        print(f"  empty-language opens: {empty_open}")
    if issues:
        for x in issues:
            print(f"  {x}")
print(f"\nTotal files: {len(results)}")

