#!/usr/bin/env python3
"""Comprehensive markdown audit summary for the java directory."""
import os, re, sys
from collections import defaultdict

ROOT = r"/mnt/e/个人知识/OneNote/java"

# Metrics
all_files = []
issues_by_type = defaultdict(list)  # type -> [(file, line, snippet)]

def add_issue(typ, file, line, snippet):
    issues_by_type[typ].append((file, line, snippet[:100]))

for dirpath, dirs, fnames in os.walk(ROOT):
    for name in sorted(fnames):
        if not name.endswith(".md"):
            continue
        path = os.path.join(dirpath, name)
        rel = os.path.relpath(path, ROOT)
        all_files.append(path)

for path in all_files:
    rel = os.path.relpath(path, ROOT).replace(os.sep, "/")
    with open(path, encoding="utf-8") as fh:
        content = fh.read()
    size = len(content)
    lines = content.split("\n")
    n_lines = len(lines)
    in_code = False
    h1_outside_code = 0
    h2_outside_code = 0
    h3_outside_code = 0
    # Adjacent bold detection
    for i, line in enumerate(lines, 1):
        s = line.strip()
        if s.startswith("```"):
            in_code = not in_code
            continue
        if in_code:
            continue
        if s.startswith("# "):
            h1_outside_code += 1
        elif s.startswith("## "):
            h2_outside_code += 1
        elif s.startswith("### "):
            h3_outside_code += 1
        # Adjacent bold: **X****Y**
        if re.search(r"\*\*[^*]+\*\*\*\*[^*]+\*\*", line):
            add_issue("adj_bold", rel, i, line)
        # Stacked image lines (no separator)
        if line.strip().startswith("![[") and i > 1:
            prev = lines[i-2].strip() if i-2 >= 0 else ""
            if prev.endswith("![[_assets/...") or (prev.startswith("![[") and prev.endswith("]]")):
                if not lines[i-1].endswith("\n") and not prev.endswith("\n\n"):
                    pass  # Optional: adjacent image detection
    # Tables
    table_lines = [line for line in lines if line.strip().startswith("|")]
    if table_lines:
        # Check for empty header
        # Find first table block
        in_table = False
        first_block = []
        for line in lines:
            if line.strip().startswith("|"):
                if not in_table:
                    in_table = True
                    first_block = []
                first_block.append(line)
            else:
                if in_table and len(first_block) >= 2:
                    break
                in_table = False
        if first_block and len(first_block) >= 2:
            first_row = first_block[0]
            cells = [c.strip() for c in first_row.strip().strip("|").split("|")]
            empty_cells = [c for c in cells if not c]
            if empty_cells and len(cells) > 1:
                add_issue("table_empty_header", rel, 1, first_row)

print(f"Total files: {len(all_files)}")
print()
for typ, items in sorted(issues_by_type.items(), key=lambda x: -len(x[1])):
    print(f"=== {typ} ({len(items)} occurrences) ===")
    seen = defaultdict(int)
    for f, ln, sn in items:
        seen[f] += 1
    for f, c in sorted(seen.items(), key=lambda x: -x[1]):
        print(f"  {f}: {c} occurrence(s)")
    print()

