#!/usr/bin/env python3
"""Categorize each file by structure pattern."""
import os, re

ROOT = r"/mnt/e/个人知识/OneNote/java"

categories = {
    "h_proper": [],         # has actual # headings
    "number_top": [],       # first line numbered list "1. xxx"
    "bold_top": [],         # first content line is **xxx**
    "image_top": [],        # first content line is image
    "code_top": [],         # first content is code block
    "prose": [],            # free text
}

for dp, ds, fn in os.walk(ROOT):
    for f in sorted(fn):
        if not f.endswith(".md"):
            continue
        path = os.path.join(dp, f)
        rel = os.path.relpath(path, ROOT).replace(os.sep, "/")
        with open(path, encoding="utf-8") as fh:
            content = fh.read()
        lines = content.split("\n")
        # Find first non-blank content (outside code fence)
        in_code = False
        first = None
        for line in lines:
            s = line.strip()
            if s.startswith("```"):
                in_code = not in_code
                continue
            if in_code: continue
            if s:
                first = line
                break
        # Also collect heading info
        in_code2 = False
        n_h_total = 0
        n_bold_only = 0
        for line in lines:
            s = line.strip()
            if s.startswith("```"):
                in_code2 = not in_code2
                continue
